def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full lines of 3 divide the grid into tiles.
    sep_rows = {r for r in range(h) if all(v == 3 for v in grid[r])}
    sep_cols = {c for c in range(w) if all(grid[r][c] == 3 for r in range(h))}

    def ranges(n, separators):
        result, start = [], 0
        for i in range(n):
            if i in separators:
                if start < i:
                    result.append((start, i))
                start = i + 1
        if start < n:
            result.append((start, n))
        return result

    row_tiles = ranges(h, sep_rows)
    col_tiles = ranges(w, sep_cols)
    tiles = [(r0, r1, c0, c1) for r0, r1 in row_tiles for c0, c1 in col_tiles]

    def count(tile):
        r0, r1, c0, c1 = tile
        return sum(grid[r][c] != 7 for r in range(r0, r1) for c in range(c0, c1))

    source = max(tiles, key=count)
    sr0, sr1, sc0, sc1 = source
    pattern = [[grid[r][c] for c in range(sc0, sc1)] for r in range(sr0, sr1)]

    out = [row[:] for row in grid]
    for r0, r1, c0, c1 in tiles:
        if (r1 - r0, c1 - c0) != (len(pattern), len(pattern[0])):
            continue
        for dr in range(len(pattern)):
            for dc in range(len(pattern[0])):
                value = pattern[dr][dc]
                if value != 7:
                    out[r0 + dr][c0 + dc] = value

    return out
